"use client";import Link from "next/link";import { useSearchParams } from "next/navigation";import { useEffect,useState } from "react";import { categories,categoryLabel,Festival } from "@/lib/types";import { seedFestivals } from "@/lib/festivals";import { filterFestivals,isPast,paginate,distanceKm } from "@/lib/utils";import { SearchForm } from "./search";import { FestivalCard } from "./festival-card";
const getSaved=()=>{try{return JSON.parse(localStorage.getItem("matsuri-submissions")||"[]") as Festival[]}catch{return[]}};
export function Home(){const q=useSearchParams(),[all,setAll]=useState(seedFestivals),[near,setNear]=useState<Festival[]>([]),[error,setError]=useState("");useEffect(()=>setAll([...getSaved(),...seedFestivals]),[]);const f=filterFestivals(all.filter(x=>!isPast(x)),Object.fromEntries(q.entries()));const page=paginate(f,Number(q.get("page"))||1);function locate(){if(!navigator.geolocation){setError("Location is unavailable. Search by prefecture or city instead.");return}navigator.geolocation.getCurrentPosition(p=>setNear([...all].filter(x=>x.latitude&&x.longitude).sort((a,b)=>distanceKm(p.coords.latitude,p.coords.longitude,a.latitude!,a.longitude!)-distanceKm(p.coords.latitude,p.coords.longitude,b.latitude!,b.longitude!)).slice(0,3)),()=>setError("Location access was not granted. Search by prefecture or city instead."));}return <><section className="hero"><div className="wrap"><h1>Find festivals<br/>in Japan</h1><p>Discover local festivals and experiences across Japan.</p><SearchForm/></div></section><main><section className="section wrap"><div className="title-row"><div><h2>Browse by category</h2><p className="muted">Start with the kind of experience you want.</p></div></div><div className="categories">{categories.map(c=><Link key={c} href={`/category/${c}`} className="category"><span>Explore</span><h3>{categoryLabel(c)}</h3></Link>)}</div></section><section className="section near" id="near"><div className="wrap"><div className="title-row"><div><h2>Festivals near me</h2><p className="muted">Use your location to see nearby prototype festival data.</p></div><button className="button" onClick={locate}>Use my location</button></div>{error&&<p className="notice">{error}</p>}{near.length>0&&<div className="grid">{near.map(x=><FestivalCard festival={x} key={x.id}/>)}</div>}</div></section><section className="section wrap"><div className="title-row"><div><h2>{q.size?"Festival results":"Upcoming Festivals"}</h2><p className="muted">{f.length} festivals to discover</p></div><Link href="/past">View past festivals →</Link></div>{page.items.length?<><div className="grid">{page.items.map(x=><FestivalCard festival={x} key={x.id}/>)}</div><div className="pagination">{page.current>1&&<Link className="button alt" href={`/?${new URLSearchParams({...Object.fromEntries(q.entries()),page:String(page.current-1)})}`}>Previous</Link>}<span>Page {page.current} of {page.total}</span>{page.current<page.total&&<Link className="button alt" href={`/?${new URLSearchParams({...Object.fromEntries(q.entries()),page:String(page.current+1)})}`}>Next</Link>}</div></>:<div className="empty"><h3>No festivals found</h3><p>Try a different date, place, or category.</p><Link className="button" href="/">Clear search</Link></div>}</section><section className="section near"><div className="wrap"><h2>Never miss a festival</h2><p>Get festival recommendations and upcoming events in Japan.</p><Link className="button" href="/newsletter">Subscribe to newsletter</Link></div></section></main></>}
