"use client";import { useRouter,useSearchParams } from "next/navigation";import { categories,categoryLabel } from "@/lib/types";
export function SearchForm(){const router=useRouter(),q=useSearchParams();function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget);const p=new URLSearchParams();fd.forEach((v,k)=>{if(v)p.set(k,String(v))});p.set("page","1");router.push(`/?${p}`)}return <form className="search" onSubmit={submit}><label className="field">YEAR<select name="year" defaultValue={q.get("year")||""}><option value="">Any year</option>{[2025,2026,2027,2028].map(y=><option key={y}>{y}</option>)}</select></label><label className="field">MONTH<select name="month" defaultValue={q.get("month")||""}><option value="">Any month</option>{Array.from({length:12},(_,i)=><option value={i+1} key={i}>{new Date(2027,i,1).toLocaleString("en",{month:"long"})}</option>)}</select></label><label className="field">PREFECTURE / CITY<input name="location" defaultValue={q.get("location")||""} placeholder="e.g. Kyoto"/></label><label className="field">CATEGORY<select name="category" defaultValue={q.get("category")||""}><option value="">All categories</option>{categories.map(c=><option value={c} key={c}>{categoryLabel(c)}</option>)}</select></label><button className="button">Search</button></form>}
