import Link from "next/link";import { Festival } from "@/lib/types";import { categoryLabel } from "@/lib/types";
export function FestivalCard({festival,ended=false}:{festival:Festival;ended?:boolean}){return <article className="card"><img src={festival.imageUrl||"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=1200&q=80"} alt="Festival scene"/><div className="card-body"><div className="eyebrow">{ended?"Ended · ":""}{categoryLabel(festival.category)}</div><div className="muted">{festival.startDate}{festival.endDate?` – ${festival.endDate}`:""}</div><h3>{festival.nameEn}</h3><div className="muted">{festival.city}, {festival.prefecture}</div><div className="tags">{festival.activities.map(a=><span className="tag" key={a}>{a}</span>)}</div><Link className="button alt" href={`/event/${festival.id}/${festival.slug}`}>View details</Link></div></article>}
